package com.pridesys.ticketing.module.service;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.*;import com.pridesys.ticketing.project.service.ProjectService;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ModuleService {private final ModuleRepository modules;private final ProjectService projects;public ModuleService(ModuleRepository m,ProjectService p){modules=m;projects=p;}public List<ModuleRecord> list(UserEntity a,long p){scope(a,p);return modules.findByProjectIdOrderByName(p).stream().map(this::map).toList();}public ModuleRecord create(UserEntity a,long p,UsersProjectsDtos.CreateModuleRequest r){scope(a,p);return map(modules.save(new ModuleEntity(p,r.name().trim(),r.description())));}public void update(UserEntity a,long p,long id,UsersProjectsDtos.UpdateModuleRequest r){scope(a,p);var m=modules.findById(id).orElseThrow();m.setName(r.name().trim());m.setDescription(r.description());if(r.active()!=null)m.setActive(r.active());modules.save(m);}public void delete(UserEntity a,long p,long id){scope(a,p);modules.deleteById(id);}private void scope(UserEntity a,long p){if(!projects.hasAccess(a,p))throw new AccessDeniedException("Project access denied");}private ModuleRecord map(ModuleEntity m){return new ModuleRecord(m.getId(),m.getProjectId(),m.getName(),m.getDescription(),m.isActive());}}
